s=s[:i]+'''const MS_PER_MINUTE = 60_000;
const GROUP_DISCOUNT_MIN_TICKETS = 4;
const CANCELLATION_FEE_CENTS_PER_TICKET = 200;

interface HoldRecord extends Hold {
  ended: boolean;
}

interface OrderRecord extends Order {
  cancelled: boolean;
}

/**
 * Computes quantity * price, minus 10 % for groups, rounded to the nearest
 * multiple of 5 cents (halves round up). Works in tenths of a cent so the
 * discount stays exact for integer prices.
 */
function orderTotalCents(quantity: number, priceCents: number): number {
  const amount = quantity * priceCents;
  const tenths = quantity >= GROUP_DISCOUNT_MIN_TICKETS ? amount * 9 : amount * 10;
  return Math.floor((tenths + 25) / 50) * 5;
}

export function createBoxOffice(options: BoxOfficeOptions): BoxOffice {
  const sections = new Map(options.sections.map((s) => [s.id, s]));
  const holds = new Map<string, HoldRecord>();
  const orders = new Map<string, OrderRecord>();
  let nextHoldNumber = 1;
  let nextOrderNumber = 1;

  const isActive = (h: HoldRecord, now: number) => !h.ended && now < h.expiresAt;

  function getSection(sectionId: string): SectionConfig {
    const section = sections.get(sectionId);
    if (!section) {
      throw new BoxOfficeError("UNKNOWN_SECTION", `Unknown section ${sectionId}`);
    }
    return section;
  }

  function taken(matches: (r: { customerId: string; sectionId: string }) => boolean, now: number): number {
    let total = 0;
    for (const h of holds.values()) {
      if (isActive(h, now) && matches(h)) total += h.quantity;
    }
    for (const o of orders.values()) {
      if (!o.cancelled && matches(o)) total += o.quantity;
    }
    return total;
  }

  function availableAt(section: SectionConfig, now: number): number {
    return section.capacity - taken((r) => r.sectionId === section.id, now);
  }

  function getOpenHold(holdId: string): HoldRecord {
    const h = holds.get(holdId);
    if (!h || h.ended) {
      throw new BoxOfficeError("UNKNOWN_HOLD", `Unknown hold ${holdId}`);
    }
    return h;
  }

  return {
    hold(customerId, sectionId, quantity) {
      const section = getSection(sectionId);
      if (!Number.isInteger(quantity) || quantity < 1) {
        throw new BoxOfficeError("INVALID_QUANTITY", `Invalid quantity ${quantity}`);
      }
      const now = options.now();
      const customerTickets = taken((r) => r.customerId === customerId, now);
      if (customerTickets + quantity > options.maxTicketsPerCustomer) {
        throw new BoxOfficeError(
          "CUSTOMER_LIMIT",
          `Customer ${customerId} may hold at most ${options.maxTicketsPerCustomer} tickets`,
        );
      }
      if (quantity > availableAt(section, now)) {
        throw new BoxOfficeError("SOLD_OUT", `Not enough tickets left in section ${sectionId}`);
      }
      const record: HoldRecord = {
        holdId: `H${nextHoldNumber++}`,
        customerId,
        sectionId,
        quantity,
        expiresAt: now + options.holdMinutes * MS_PER_MINUTE,
        ended: false,
      };
      holds.set(record.holdId, record);
      const { ended: _ended, ...hold } = record;
      return hold;
    },

    confirm(holdId) {
      const h = getOpenHold(holdId);
      if (options.now() >= h.expiresAt) {
        throw new BoxOfficeError("HOLD_EXPIRED", `Hold ${holdId} has expired`);
      }
      h.ended = true;
      const record: OrderRecord = {
        orderId: `O${nextOrderNumber++}`,
        customerId: h.customerId,
        sectionId: h.sectionId,
        quantity: h.quantity,
        totalCents: orderTotalCents(h.quantity, getSection(h.sectionId).priceCents),
        cancelled: false,
      };
      orders.set(record.orderId, record);
      const { cancelled: _cancelled, ...order } = record;
      return order;
    },

    release(holdId) {
      const h = getOpenHold(holdId);
      if (options.now() >= h.expiresAt) return;
      h.ended = true;
    },

    cancelOrder(orderId) {
      const o = orders.get(orderId);
      if (!o || o.cancelled) {
        throw new BoxOfficeError("UNKNOWN_ORDER", `Unknown order ${orderId}`);
      }
      o.cancelled = true;
      return Math.max(0, o.totalCents - o.quantity * CANCELLATION_FEE_CENTS_PER_TICKET);
    },

    available(sectionId) {
      return availableAt(getSection(sectionId), options.now());
    },
  };
}
'''
open(p,'w').write(s)
EOF

cat >> src/boxOffice.test.ts <<'EOF'

import { createBoxOffice, type BoxOfficeErrorCode } from "./boxOffice";

function setup(overrides: { maxTicketsPerCustomer?: number } = {}) {
  let time = 1_000_000;
  const office = createBoxOffice({
    sections: [
      { id: "PARKETT", capacity: 10, priceCents: 4990 },
      { id: "BALKON", capacity: 3, priceCents: 2500 },
      { id: "CHEAP", capacity: 10, priceCents: 150 },
    ],
    holdMinutes: 10,
    maxTicketsPerCustomer: overrides.maxTicketsPerCustomer ?? 6,
    now: () => time,
  });
  return { office, advance: (ms: number) => (time += ms), now: () => time };
}

function expectCode(fn: () => unknown, code: BoxOfficeErrorCode) {
  try {
    fn();
  } catch (e) {
    expect(e).toBeInstanceOf(BoxOfficeError);
    expect((e as BoxOfficeError).code).toBe(code);
    return;
  }
  throw new Error(`expected ${code}`);
}

describe("hold", () => {
  test("creates sequential holds and reduces availability", () => {
    const { office, now } = setup();
    const h = office.hold("alice", "PARKETT", 2);
    expect(h).toEqual({ holdId: "H1", customerId: "alice", sectionId: "PARKETT", quantity: 2, expiresAt: now() + 600_000 });
    expectCode(() => office.hold("bob", "BALKON", 4), "SOLD_OUT");
    expect(office.hold("bob", "BALKON", 3).holdId).toBe("H2");
    expect(office.available("PARKETT")).toBe(8);
    expect(office.available("BALKON")).toBe(0);
  });

  test("validates in order", () => {
    const { office } = setup();
    expectCode(() => office.hold("a", "NOPE", 0), "UNKNOWN_SECTION");
    expectCode(() => office.hold("a", "PARKETT", 0), "INVALID_QUANTITY");
    expectCode(() => office.hold("a", "PARKETT", 1.5), "INVALID_QUANTITY");
    expectCode(() => office.hold("a", "BALKON", 7), "CUSTOMER_LIMIT");
    expectCode(() => office.available("NOPE"), "UNKNOWN_SECTION");
  });

  test("customer limit spans sections and orders", () => {
    const { office } = setup();
    office.confirm(office.hold("a", "PARKETT", 3).holdId);
    office.hold("a", "BALKON", 2);
    expectCode(() => office.hold("a", "PARKETT", 2), "CUSTOMER_LIMIT");
    expect(office.hold("a", "PARKETT", 1).holdId).toBe("H3");
  });

  test("expired holds stop counting at expiresAt", () => {
    const { office, advance } = setup();
    office.hold("a", "BALKON", 3);
    advance(600_000 - 1);
    expect(office.available("BALKON")).toBe(0);
    advance(1);
    expect(office.available("BALKON")).toBe(3);
    expect(office.hold("a", "BALKON", 3).holdId).toBe("H2");
  });
});

describe("confirm / release", () => {
  test("confirm creates order and keeps tickets", () => {
    const { office } = setup();
    const h = office.hold("a", "BALKON", 2);
    const o = office.confirm(h.holdId);
    expect(o).toEqual({ orderId: "O1", customerId: "a", sectionId: "BALKON", quantity: 2, totalCents: 5000 });
    expect(office.available("BALKON")).toBe(1);
    expectCode(() => office.confirm(h.holdId), "UNKNOWN_HOLD");
    expectCode(() => office.release(h.holdId), "UNKNOWN_HOLD");
    expectCode(() => office.confirm("H99"), "UNKNOWN_HOLD");
  });

  test("expired hold cannot be confirmed, release is a no-op", () => {
    const { office, advance } = setup();
    const h = office.hold("a", "BALKON", 2);
    advance(600_000);
    expectCode(() => office.confirm(h.holdId), "HOLD_EXPIRED");
    office.release(h.holdId);
    expect(office.available("BALKON")).toBe(3);
  });

  test("release frees tickets", () => {
    const { office } = setup();
    const h = office.hold("a", "BALKON", 3);
    office.release(h.holdId);
    expect(office.available("BALKON")).toBe(3);
    expectCode(() => office.release(h.holdId), "UNKNOWN_HOLD");
    expectCode(() => office.confirm(h.holdId), "UNKNOWN_HOLD");
  });
});

describe("pricing and cancellation", () => {
  test("group discount and Rappen rounding", () => {
    const { office } = setup();
    // 4 * 4990 = 19960 * 0.9 = 17964 -> 17965
    expect(office.confirm(office.hold("a", "PARKETT", 4).holdId).totalCents).toBe(17965);
    // 3 * 4990 = 14970, no discount
    expect(office.confirm(office.hold("b", "PARKETT", 3).holdId).totalCents).toBe(14970);
  });

  test("rounding without discount and halves round up", () => {
    let time = 0;
    const office = createBoxOffice({
      sections: [{ id: "S", capacity: 100, priceCents: 1001 }, { id: "T", capacity: 100, priceCents: 1025 }],
      holdMinutes: 5,
      maxTicketsPerCustomer: 100,
      now: () => time,
    });
    expect(office.confirm(office.hold("a", "S", 1).holdId).totalCents).toBe(1000);
    expect(office.confirm(office.hold("a", "S", 3).holdId).totalCents).toBe(3005);
    // 5 * 1025 = 5125 * 0.9 = 4612.5 -> 4610
    expect(office.confirm(office.hold("a", "T", 5).holdId).totalCents).toBe(4610);
    // 1 * 1025 -> 1025 ; 1 * 1001 -> 1000 ; check 2.5 cents up: 4 * 1005 = 4020 * 0.9 = 3618 -> 3620
  });

  test("cancel refunds minus fee and frees tickets", () => {
    const { office } = setup();
    const o = office.confirm(office.hold("a", "BALKON", 2).holdId);
    expect(office.cancelOrder(o.orderId)).toBe(4600);
    expect(office.available("BALKON")).toBe(3);
    expectCode(() => office.cancelOrder(o.orderId), "UNKNOWN_ORDER");
    expectCode(() => office.cancelOrder("O9"), "UNKNOWN_ORDER");
    const cheap = office.confirm(office.hold("a", "CHEAP", 6).holdId);
    expect(office.cancelOrder(cheap.orderId)).toBe(0);
  });
});
EOF
